{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise TypeError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("case requires nodes and required_symbols")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list):
        raise TypeError("nodes must be an array")
    if not isinstance(required_symbols, list) or any(not isinstance(s, str) for s in required_symbols):
        raise TypeError("required_symbols must be an array of strings")

    required = set(required_symbols)
    by_id = {}
    roots = []
    fields = ("id", "parent", "symbol", "depth", "removable", "utility")

    for node in nodes:
        if not isinstance(node, dict):
            raise TypeError("each node must be an object")
        if any(field not in node for field in fields):
            raise ValueError("each node requires id, parent, symbol, depth, removable, and utility")
        node_id = node["id"]
        parent = node["parent"]
        depth = node["depth"]
        utility = node["utility"]
        if not isinstance(node_id, str) or node_id in by_id:
            raise ValueError("node IDs must be unique strings")
        if parent is not None and not isinstance(parent, str):
            raise TypeError("parent must be a string or null")
        if not isinstance(node["symbol"], str):
            raise TypeError("symbol must be a string")
        if isinstance(depth, bool) or not isinstance(depth, int) or depth < 0:
            raise TypeError("depth must be a nonnegative integer")
        if not isinstance(node["removable"], bool):
            raise TypeError("removable must be boolean")
        if isinstance(utility, bool) or not isinstance(utility, (int, float)) or not math.isfinite(utility):
            raise TypeError("utility must be a finite number")
        by_id[node_id] = node
        if parent is None:
            roots.append(node_id)

    if len(roots) != 1:
        raise ValueError("nodes must contain exactly one root")
    root_id = roots[0]
    if by_id[root_id]["depth"] != 0:
        raise ValueError("root depth must be zero")

    children = {node_id: set() for node_id in by_id}
    for node_id, node in by_id.items():
        parent = node["parent"]
        if parent is not None:
            if parent not in by_id:
                raise ValueError("parent must reference an existing node")
            if parent == node_id:
                raise ValueError("a node cannot parent itself")
            if node["depth"] != by_id[parent]["depth"] + 1:
                raise ValueError("node depth must be parent depth plus one")
            children[parent].add(node_id)

    represented = {node["symbol"] for node in nodes}
    if not required.issubset(represented):
        raise ValueError("all required symbols must be represented")

    retained = set(by_id)
    removed = []
    candidates = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))
    for node in candidates:
        node_id = node["id"]
        if node_id == root_id or not node["removable"] or node["symbol"] in required:
            continue
        if any(child in retained for child in children[node_id]):
            continue
        remaining_symbols = {by_id[other]["symbol"] for other in retained if other != node_id}
        if not required.issubset(remaining_symbols):
            continue
        retained.remove(node_id)
        removed.append(node_id)

    return {
        "removed_node_ids": removed,
        "retained_node_ids": sorted(retained),
    }
"}
